#include "dfre/mission_character_instance.hpp"
#include "dfre/mission_character_resource.hpp"
#include "dfre/mission_actor_resources.hpp"
#include "dfre/mission_sound_runtime.hpp"
#include <fstream>
#include <iostream>
#include <map>
#include <set>
#include <stdexcept>
using namespace dfre;using U=std::uint32_t;
namespace {
void check(bool n,const char* text){if(!n)throw std::runtime_error(text);}template<class F>void fails(F f){bool stopped=false;try{f();}catch(const std::exception&){stopped=true;}check(stopped,"Required error did not stop");}
void basic(){std::map<U,std::uint8_t> bytes;auto put=[&](U a,U w,U n){for(U i=0;i<w;++i)bytes[a+i]=std::uint8_t(n>>(8*i));};auto get=[&](U a,U w){U n=0;for(U i=0;i<w;++i)n|=U(bytes[a+i])<<(8*i);return n;};MissionCharacterInstanceBindings b{{get,put,{}},{}};MissionCharacterAllocateRegisters r{1,0,3,4,0x1000,0x2000,7};put(0x1058,4,0x24);put(0x1014,4,1);put(0x1080,4,0x3000);put(0x1084,4,0x4000);put(0x300c,4,1);put(0x4010,4,0xfeed);fails([&]{mission_character_instance_delta(b,r);});check(get(0x400c,4)==0&&get(0x4010,4)==0xfeed&&r.edx==0,"Division failure prefix");
 r={1,1,3,4,0x1000,0x2000,7};put(0x2004,4,0x80);put(0x2025,1,0);put(0x3004,4,0);put(0x4034,4,0xbeef);fails([&]{mission_character_instance_immediate(b,r);});check(r.ebx==0&&get(0x4034,4)==0xbeef,"Immediate head uses last Y angle divisor");
 r={1,2,3,4,0x1000,0x2000,7};put(0x2000,4,0x31524843);put(0x2010,4,1);fails([&]{mission_character_instance_construct(b,r);});check(get(0x1000,4)==0x2000&&get(0x1058,4)==0x34&&r.ecx==0x81c,"Missing allocator retains constructor prefix");
}
void stock(const std::filesystem::path& folder){AssetStore assets(folder);std::ifstream file(folder/"Df.exe",std::ios::binary);AssetBytes exe((std::istreambuf_iterator<char>(file)),{});Fixed3 listener{};U yaw=0;MissionAudioFrameCells audio{0,listener,yaw};const TerrainGeometry* terrain=nullptr;std::unique_ptr<MissionCharacterAllocateState> pool;MissionSoundRuntimeBindings host;
 host.record_base=[&](U a,U w)->std::optional<U>{if(pool&&pool->claims(a,w))return mission_character_instance_base;return std::nullopt;};host.record_read=[&](U base,U off,U w){return pool->read(base+off,w);};host.record_store=[&](U base,U off,U w,U n){pool->write(base+off,w,n);};MissionSoundRuntime sound(assets,exe,audio,terrain,host);const auto& m=sound.asset_bindings();std::array<std::uint8_t,mission_character_source_bytes> cold{};for(U i=0;i<cold.size();++i)cold[i]=std::uint8_t(m.read(mission_character_instance_base+i,1));pool=std::make_unique<MissionCharacterAllocateState>(cold.data(),cold.size());
 MissionDebriefBindings resource{m.read,m.write,{}};resource.call=[&](U site,const auto& args)->U{if(site==0x499e5e){for(U i=0;;++i){U x=m.read(args[0]+i,1),y=m.read(args[1]+i,1);if(x>='a'&&x<='z')x-=32;if(y>='a'&&y<='z')y-=32;if(x!=y)return 1;if(!x)return 0;}}return m.call(site,args);};const U scratch=m.call(0x497f60,{0x100,4,0,0}),frame=scratch+0x7c,name=m.call(0x497f60,{64,4,0,0});const std::string filename="PLAYER01.CHR";for(U i=0;i<=filename.size();++i)m.write(name+i,1,i<filename.size()?std::uint8_t(filename[i]):0);m.write(frame+0x14,4,name);const U row=mission_character_resource_load(resource,frame);check(row==0x6ba440,"Physical CHR registry row");
 MissionCharacterInstanceBindings b;b.memory.read=m.read;b.memory.write=m.write;b.allocate=[&](U size,U align,U flags,U label){return m.call(0x497f60,{size,align,flags,label});};b.memory.call=[&](U site,MissionCharacterAllocateRegisters& regs){if(site==0x439c70)mission_character_allocate_raw(b.memory,regs);else if(site==0x439e48)mission_character_instance_construct(b,regs);else if(site==0x43a690)mission_character_instance_frame(b,regs);else if(site==0x43a0e0)mission_character_seed_pose(b.memory,regs);else if(site==0x43a150)mission_character_select_action(b.memory,regs);else throw std::runtime_error("Required raw character service");};MissionCharacterAllocateRegisters r{1,2,3,4,5,6,7};const U instance=mission_character_allocate(b.memory,row,r,frame);check(instance==mission_character_instance_base&&pool->read(mission_character_occupied_base,1)==1,"Actual allocator physical slot");const U payload=m.read(instance+4,4),chr=m.read(row+0x60,4);check(payload&&m.read(instance,4)==chr&&m.read(instance+0x14,4)==m.read(chr+0x10,4),"Constructor owns current real arena arrays");check(m.read(instance+0xc,4)!=0&&m.read(instance+0x10,4)!=0,"Actual source action selected");const U pose=m.read(instance+0x80,4),delta=m.read(instance+0x84,4);check(pose>=payload&&delta>pose,"Pose and scalar storage is in source allocation");
 r={0,0,0,0,instance,0,0};check(mission_character_select_action(b.memory,r),"Source action decoder");auto live=[&](U p){const U ctx=m.read(0x5013a0,4);U at=m.read(ctx+8,4);std::set<U> seen;while(at){check(seen.insert(at).second,"Arena cycle");if(at+16==p)return true;at=m.read(at+12,4);}return false;};check(live(payload),"Source pose allocation is live");const U retained=m.read(pose,4);mission_character_release({m.read,m.write,m.call},instance);check(pool->read(mission_character_occupied_base,1)==0&&!live(payload)&&m.read(pose,4)==retained,"42CD30 releases header and occupied byte, retains arena data");r={};const U reused=mission_character_allocate(b.memory,row,r,frame);check(reused==instance&&pool->read(mission_character_occupied_base,1)==1&&live(m.read(instance+4,4)),"Released physical slot reused");mission_character_release({m.read,m.write,m.call},reused);mission_character_resources_clear({m.read,m.write,m.call});check(m.read(0x6bbd40,4)==0,"Source registry release");std::cout<<"Actual CHR resource, arena constructor, seed/action, release and physical reuse passed\n";
}
}
int main(int argc,char** argv){try{basic();if(argc==2)stock(argv[1]);else check(argc==1,"Use native_mission_character_instance [GAME_FOLDER]");return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
